[CmdletBinding()]
param([Parameter(Mandatory)][string]$ResultPath,[Parameter(Mandatory)][string]$ResourceResultPath,[switch]$Fixture)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
function Resolve-Safe([string]$Path,[string]$Description){$full=if([IO.Path]::IsPathRooted($Path)){[IO.Path]::GetFullPath($Path)}else{[IO.Path]::GetFullPath((Join-Path $repo $Path))};$prefix=$repo.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description escapes repository."};$current=$repo;foreach($part in @($full.Substring($prefix.Length).Split('\')|?{$_.Length})){$current=Join-Path $current $part;if((Test-Path -LiteralPath $current)-and((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)){throw "$Description traverses a reparse point."}};if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "$Description is missing."};$full}
$result=Resolve-Safe $ResultPath 'M5-014 result';$resource=Resolve-Safe $ResourceResultPath 'M5-013 result';if($Fixture){$fixturePrefix=(Join-Path $repo 'private/evidence/M5-014/test-');if(-not$result.StartsWith($fixturePrefix,[StringComparison]::OrdinalIgnoreCase)-or-not$resource.StartsWith($fixturePrefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Fixture bypass is restricted to an M5-014 test root.'}}else{$runRoot=Split-Path $result -Parent;$evidenceRoot=Join-Path $repo 'private/evidence/M5-014';if((Split-Path $runRoot -Parent)-cne$evidenceRoot-or(Split-Path $runRoot -Leaf)-notmatch'^20\d{6}-\d{6}-[0-9a-f]{8}$'-or(Split-Path $result -Leaf)-cne'result.json'){throw 'Physical M5-014 result must use the canonical evidence topology.'};$children=@(Get-ChildItem -LiteralPath $runRoot -Force);if($children.Count-ne2-or@($children|Where-Object{$_.PSIsContainer}).Count-ne0-or(@($children.Name|Sort-Object)-join',')-cne'M5-014-vertical-slice-report.md,result.json'){throw 'Physical M5-014 evidence children are not exact.'};$resourceProbe=& (Join-Path $PSScriptRoot 'verify-race-resource-smoke.ps1') -ResultPath $resource;if($resourceProbe.Decision-cne'five-race-bounded-resource-growth-pass'-or-not$resourceProbe.DataIntegrityVerified){throw 'Physical M5-013 result did not reverify.'}};$record=Get-Content $result -Raw|ConvertFrom-Json;$props=@('schema','task','decision','checklist','report_sha256','scope');if(($record.PSObject.Properties.Name-join',')-cne($props-join',')-or$record.schema-cne'mcla-vertical-slice-report-v1'-or$record.task-cne'M5-014'-or$record.decision-cne'go-m6-first-playable-race-vertical-slice'-or$record.scope-cne'sanitized public-artifact checklist for one pinned-save, one-controller, one-event-series vertical slice; explicit exclusions remain open'){throw 'M5-014 result identity is invalid.'};if(@($record.checklist).Count-ne14){throw 'Checklist must contain 14 tasks.'}
$expectedTasks=1..14|%{'M5-{0:D3}'-f$_};$expectedDecisions=@('pinned-save-sunset-strip-race-v1','world-rpf-streaming-pass','rendering-categories-pass','host-rtv-ordering-depth-bounded-s2','representative-material-pipeline-pass','saved-gameplay-input-pass','ffb-withheld-host-rumble-bounded','stock-30-fixed-step-and-real-time-throughput-pass','six-class-audio-stream-presence-pass','canonical-route-streaming-io-allocator-bounded-pass','save-content-prerequisite-pass','first-series-results-return-and-release-restart-pass','five-race-bounded-resource-growth-pass','vertical-slice-regression-report-pass');for($i=0;$i-lt14;$i++){$entry=$record.checklist[$i];$prefix="M5-{0:D3}-"-f($i+1);if(($entry.PSObject.Properties.Name-join',')-cne'task,decision,evidence,artifact_sha256'-or$entry.task-cne$expectedTasks[$i]-or$entry.decision-cne$expectedDecisions[$i]-or-not$entry.evidence.StartsWith($prefix,[StringComparison]::Ordinal)){throw "Checklist entry $($i+1) is malformed."};$doc=Join-Path $repo ('docs/evidence/'+$entry.evidence);if($i-lt13-and-not(Test-Path -LiteralPath $doc -PathType Leaf)){throw "Public evidence doc for $($entry.task) is missing."}}
$historical=@(
  @('config/first-race-route.json','6E3732ACA6DAC024937E79F5823E4C50D0FDE2F89CBD881CF0FF2B21EEACFD8F'),
  @('private/evidence/M5-002/20260814-093131-ddca5b9d/result.json','A582A41BB254D9187BC6F8147E89E2FF2E92D0EA4B79945760BA6FBCF334BC28'),
  @('private/evidence/M5-003/20260814-104624-fde51a30/result.json','299392E59CB38AFB44256E773884856FF0C869A96D2045086A65396C1ED4EFCA'),
