for($i=0;$i-lt$historical.Count;$i++){$path=Resolve-Safe $historical[$i][0] "Historical M5 artifact $($i+1)";$hash=(Get-FileHash $path -Algorithm SHA256).Hash;if($hash-cne$historical[$i][1]-or$record.checklist[$i].artifact_sha256-cne$hash){throw "Historical M5 artifact $($i+1) drifted."}}
$resourceJson=Get-Content $resource -Raw|ConvertFrom-Json;if($resourceJson.task-cne'M5-013'-or$resourceJson.decision-cne'five-race-bounded-resource-growth-pass'-or$record.checklist[12].artifact_sha256-cne(Get-FileHash $resource -Algorithm SHA256).Hash-or$record.checklist[13].artifact_sha256-cne'SELF'){throw 'M5-013/M5-014 binding is invalid.'};$report=Resolve-Safe (Join-Path (Split-Path $result -Parent) 'M5-014-vertical-slice-report.md') 'Sanitized report';if((Get-FileHash $report -Algorithm SHA256).Hash-cne$record.report_sha256){throw 'Report hash drifted.'};$text=[IO.File]::ReadAllText($report);foreach($bad in @('private/evidence','B13EBABEBABEBABE')){if($text.Contains($bad,[StringComparison]::OrdinalIgnoreCase)){throw "Report leaks forbidden token '$bad'."}};foreach($pattern in @('(?i)[A-Z]:[\\/]','(?i)/(?:home|Users)/','(?i)(?<![A-F0-9])[A-F0-9]{64}(?![A-F0-9])')){if([regex]::IsMatch($text,$pattern)){throw "Report leaks forbidden path or digest pattern '$pattern'."}};foreach($task in $expectedTasks){if(-not$text.Contains("| $task |")){throw "Report is missing $task."}};foreach($needle in @('GO M6','one pinned-save','not first-run/OOBE coverage','docs/known-issues.md','Five repeated race completions')){if(-not$text.Contains($needle,[StringComparison]::OrdinalIgnoreCase)){throw "Report scope is missing '$needle'."}}
if(-not$Fixture){$publicReport=Resolve-Safe (Join-Path $repo 'docs/evidence/M5-014-vertical-slice-report.md') 'Tracked M5-014 report';$publicText=[IO.File]::ReadAllText($publicReport);if(($publicText-replace"`r`n","`n")-cne($text-replace"`r`n","`n")){throw 'Tracked M5-014 report drifted from the accepted sanitized report.'}}
[pscustomobject][ordered]@{Decision=$record.decision;TasksLinked=14;SanitizedReportVerified=$true;ResourceResultBound=$true;PublicReportBound=(-not$Fixture);ReadyForPublication=$true}
